        trigger_mode = 2
      },
      [8] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 2,
        sentence = "( *^-^)是你准备在我们回家前剪辑好送给我的礼物？",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [9] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 5,
        sentence = "你怎么知道……？",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [10] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 2,
        sentence = "因为我的小姑娘刚才嘟囔的梦话都在说——",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [11] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 2,
        sentence = "“没几天了，要快点剪好”",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [12] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 2,
        sentence = "所以我才想看看，到底是什么这么让你挂心。",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [13] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 2,
        sentence = "然后就发现，原来这几天我弹琴的时候……",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [14] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 2,
        sentence = "大制作人的摄影机一直都在悄悄运行。",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [15] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 5,
        sentence = "我就是觉得这个画面太珍贵了嘛。",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [16] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 2,
        sentence = "傻瓜，我当然知道你的心意。",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [17] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 2,
        sentence = "所以才想试试我在大制作人身边这么久——",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [18] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 2,
        sentence = "有没有学到剪辑的皮毛。",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [19] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 5,
        sentence = "噗，我来看看。剪辑条很干净，看起来也很连贯。",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [20] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 5,
        sentence = "虽然许剪辑师很优秀，但还是有个明显不如我的地方~",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [21] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 2,
        sentence = "是什么？",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      },
      [22] = {
        qq_res = "15059/anime_g.prefab",
        speak_role_id = 5,
        sentence = "o(〃'▽'〃)o你对影像里这位主人公的爱意不及我~",
        animation_mode = 1,
        animation_res = "15059/anime_g.prefab",
        trigger_mode = 2
      }
    },
    [3006] = {
      [1] = {
        qq_res = "15059/anime_h.prefab",
        speak_role_id = 2,
        sentence = "( *^-^)时隔几个月，又一次拥抱了晨起的第一缕阳光。",
