        trigger_mode = 2
      },
      [8] = {
        qq_res = "15059/anime_h.prefab",
        speak_role_id = 2,
        sentence = "( *^-^)你泡的茶很好喝。",
        animation_mode = 1,
        animation_res = "15059/anime_h.prefab",
        trigger_mode = 2
      },
      [9] = {
        qq_res = "15059/anime_h.prefab",
        speak_role_id = 5,
        sentence = "那多亏了许教授的耳濡目染~不过我可不是在讨夸奖哦！",
