        animation_res = "15059/anime_h.prefab",
        trigger_mode = 2
      },
      [10] = {
        qq_res = "15059/anime_h.prefab",
        speak_role_id = 5,
        sentence = "你就没有觉得自己身上有什么变化？",
        animation_mode = 1,
        animation_res = "15059/anime_h.prefab",
        trigger_mode = 2
      },
      [11] = {
        qq_res = "15059/anime_h.prefab",
        speak_role_id = 2,
        sentence = "嗯……如果$u这么问的话——",
        animation_mode = 1,
        animation_res = "15059/anime_h.prefab",
        trigger_mode = 2
      },
      [12] = {
        qq_res = "15059/anime_h.prefab",
        speak_role_id = 2,
        sentence = "每一天，我都会发现自己对$u更心动一点。",
        animation_mode = 1,
        animation_res = "15059/anime_h.prefab",
        trigger_mode = 2
      },
      [13] = {
        qq_res = "15059/anime_h.prefab",
        speak_role_id = 5,
        sentence = "(・ω・）虽然我也是，但我也不是在说这个啦~",
        animation_mode = 1,
        animation_res = "15059/anime_h.prefab",
        trigger_mode = 2
      },
      [14] = {
        qq_res = "15059/anime_h.prefab",
