        animation_res = "15059/anime_h.prefab",
        trigger_mode = 2
      },
      [15] = {
        qq_res = "15059/anime_h.prefab",
        speak_role_id = 2,
        sentence = "其实……从你的眼睛里能看得很清楚。",
