        speak_role_id = 1,
        sentence = "算不上。",
        animation_mode = 1,
        animation_res = "15061/anime_b.prefab",
        trigger_mode = 2
      },
      [8] = {
        qq_res = "15061/anime_b.prefab",
        speak_role_id = 5,
        sentence = "那你为什么还这么小心翼翼地照顾它？",
